<?php
namespace App\Application\Sso;
use Illuminate\Support\Facades\Http;use Illuminate\Support\Facades\Log;use RuntimeException;use Throwable;
class PermissionService { public function fetch(string $userId,string $moduleId):array{try{$response=Http::connectTimeout(config('gpha_sso.connect_timeout_seconds'))->timeout(config('gpha_sso.timeout_seconds'))->acceptJson()->withHeaders(['X-App-Id'=>config('gpha_sso.app_id'),'X-App-Key'=>config('gpha_sso.app_key')])->get(config('gpha_sso.permissions_endpoint'),['userId'=>$userId,'moduleId'=>$moduleId]);}catch(Throwable $e){Log::error('CentralLogin permission lookup failed',['reason'=>$e->getMessage()]);throw new RuntimeException('CentralLogin permissions are temporarily unavailable.');}if(!$response->successful()){Log::error('CentralLogin permission lookup rejected',['status'=>$response->status()]);throw new RuntimeException($response->status()===401?'CentralLogin rejected the EMS trusted application credentials.':'CentralLogin permissions are temporarily unavailable.');}$codes=$this->codes($response->json());$normalized=[];foreach($codes as $code){$parts=explode('.',$code);if(count($parts)<3||strcasecmp($parts[0],config('gpha_sso.app_id'))!==0)continue;$component=$this->key($parts[count($parts)-2]);$permission=$this->key($parts[count($parts)-1]);$normalized[$component][]=$permission;}return array_map(fn($p)=>array_values(array_unique($p)),$normalized);} private function codes(mixed $payload):array{$found=[];$walk=function($v)use(&$walk,&$found){if(is_string($v)&&substr_count($v,'.')>=2)$found[]=$v;elseif(is_array($v)){foreach(['permissionCode','code','fullCode','name'] as $k)if(isset($v[$k])&&is_string($v[$k])&&substr_count($v[$k],'.')>=2)$found[]=$v[$k];foreach($v as $item)$walk($item);}};$walk($payload);return array_values(array_unique($found));} public function allows(string $component,string $permission):bool{$map=session('sso.permissions',[]);return in_array($this->key($permission),(array)($map[$this->key($component)]??[]),true);} public function hasAny():bool{return collect(session('sso.permissions',[]))->contains(fn($v)=>is_array($v)&&$v!==[]);} private function key(string $v):string{return strtolower(preg_replace('/[^a-zA-Z0-9]+/','',$v)??'');} }
